DELETE FROM re_vendor_invoice_items WHERE invoice_id=? AND company_id=?")->execute([$id,$companyId]);$lineStmt=$conn->prepare("INSERT INTO re_vendor_invoice_items (company_id,invoice_id,expense_account_id,building_id,unit_id,lease_id,service_name,description,line_description,quantity,unit_price,subtotal,vat_treatment,vat_rate,vat_amount,line_total,total_price) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)");foreach($valid as $ln){$lineStmt->execute([$companyId,$id,$ln['expense_account_id'],$ln['building_id']?:null,$ln['unit_id']?:null,$ln['lease_id']?:null,$ln['description']?:'Bill line',$ln['description']?:null,$ln['description']?:null,$ln['quantity'],$ln['unit_price'],$ln['subtotal'],$ln['vat_treatment'],$ln['vat_rate'],$ln['vat_amount'],$ln['line_total'],$ln['line_total']]);}re_ap_audit($conn,$companyId,(int)$bill['vendor_id'],$id,null,'bill_edited',null,null,$total,'Vendor bill edited',$userId,'vendor_bill_edit');$conn->commit();$success='Bill updated.';$bill=re_ap_load_bill($conn,$companyId,$id);}catch(Throwable $e){if($conn->inTransaction())$conn->rollBack();$error=$e->getMessage();}}
