<?php if($success): ?><div class="alert alert-success"><?=h($success)?></div><?php endif; ?><?php if($error): ?><div class="alert alert-danger"><?=h($error)?></div><?php endif; ?><div class="d-flex justify-content-between align-items-center mb-4"><div class="page-header-label">Edit Vendor Bill <?=h($bill['invoice_number'])?></div><a href="vendor_bill_view.php?id=<?=$id?>" class="btn btn-outline-secondary">View Bill</a></div><?php if(!empty($_GET['unposted'])&&!$isPosted): ?><div class="alert alert-info">This bill was unposted and is back to draft with the same bill number. Correct the amount below, save, then post it again from the Vendor Bills list.</div><?php endif; ?><?php if($isPosted): ?><div class="alert alert-warning">This bill is already posted, so direct editing is blocked. Open the bill view and use <strong>Edit Amount (Unpost)</strong> to reverse the posted journal and edit this same bill, or <strong>Void / Amend</strong> to void it and start an amended copy. <a href="vendor_bill_view.php?id=<?=$id?>" class="btn btn-sm btn-warning ms-2">Open Bill</a></div><?php endif; ?>
<form method="post" class="card card-round"><div class="card-body"><?php csrf_field(); ?><div class="row g-3"><div class="col-md-3"><label>Bill #</label><input name="invoice_number" class="form-control" value="<?=h($bill['invoice_number'])?>" <?=$isPosted?'readonly':''?>></div><div class="col-md-3"><label>Bill Date</label><input type="date" name="invoice_date" class="form-control" value="<?=h($bill['invoice_date'])?>" <?=$isPosted?'readonly':''?>></div><div class="col-md-3"><label>Due Date</label><input type="date" name="due_date" class="form-control" value="<?=h($bill['due_date'])?>" <?=$isPosted?'readonly':''?>></div><div class="col-md-3"><label>Terms</label><input name="payment_terms" class="form-control" value="<?=h($bill['payment_terms']??'')?>" <?=$isPosted?'readonly':''?>></div><div class="col-md-3"><label>Place</label><input name="place_of_supply" class="form-control" value="<?=h($bill['place_of_supply']??'Dubai')?>" <?=$isPosted?'readonly':''?>></div><div class="col-md-3"><label>VAT Treatment</label><select name="vat_treatment" class="form-select" <?=$isPosted?'disabled':''?>><?php foreach(['vat_registered','non_vat','exempt','out_of_scope'] as $v): ?><option value="<?=$v?>" <?=($bill['vat_treatment']??'')===$v?'selected':''?>><?=h($v)?></option><?php endforeach; ?></select></div><div class="col-md-3"><label>Order/LPO</label><input name="order_number" class="form-control" value="<?=h($bill['order_number']??'')?>" <?=$isPosted?'readonly':''?>></div><div class="col-md-3"><label>Permit #</label><input name="permit_number" class="form-control" value="<?=h($bill['permit_number']??'')?>" <?=$isPosted?'readonly':''?>></div><div class="col-12"><label>Notes</label><textarea name="notes" class="form-control" <?=$isPosted?'readonly':''?>><?=h($bill['notes']??'')?></textarea></div></div><hr><h6>Lines</h6><div class="table-responsive"><table class="table table-sm" id="billLines"><thead><tr><th>Description</th><th>Expense Account</th><th>Qty</th><th>Rate</th><th>VAT</th><th>Building</th><th>Lease</th><th>Total</th><th></th></tr></thead><tbody></tbody></table></div><?php if(!$isPosted): ?><button type="button" id="addLine" class="btn btn-sm btn-outline-primary">Add Line</button><hr><button class="btn btn-primary">Save Changes</button><?php endif; ?></div></form>
<script>const accounts=<?=json_encode($accounts)?>,buildings=<?=json_encode($buildings)?>,leases=<?=json_encode($leases)?>,existing=<?=json_encode($lines)?>,locked=<?=json_encode($isPosted)?>;let idx=0;function opts(list,val,label,sel){return list.map(x=>`<option value="${x[val]}" ${String(x[val])===String(sel)?'selected':''}>${x[label]}</option>`).join('')}function addLine(data={}){const tr=document.createElement('tr');tr.innerHTML=`<td><input name="items[${idx}][description]" class="form-control form-control-sm" value="${data.service_name||data.line_description||''}" ${locked?'readonly':''}></td><td><select name="items[${idx}][expense_account_id]" class="form-select form-select-sm" ${locked?'disabled':''}><option value="">-- Account --</option>${accounts.map(a=>`<option value="${a.id}" ${String(a.id)===String(data.expense_account_id||'')?'selected':''}>${a.account_code} ${a.account_name}</option>`).join('')}</select></td><td><input type="number" step="0.01" name="items[${idx}][quantity]" class="form-control form-control-sm qty" value="${data.quantity||1}" ${locked?'readonly':''}></td><td><input type="number" step="0.01" name="items[${idx}][unit_price]" class="form-control form-control-sm rate" value="${data.unit_price||0}" ${locked?'readonly':''}></td><td><select name="items[${idx}][vat_treatment]" class="form-select form-select-sm" ${locked?'disabled':''}><option value="standard" ${(data.vat_treatment||'standard')==='standard'?'selected':''}>5%</option><option value="exempt" ${data.vat_treatment==='exempt'?'selected':''}>Exempt</option><option value="zero_rated" ${data.vat_treatment==='zero_rated'?'selected':''}>Zero</option><option value="out_of_scope" ${data.vat_treatment==='out_of_scope'?'selected':''}>OOS</option></select><input type="hidden" name="items[${idx}][vat_rate]" value="${data.vat_rate||5}"></td><td><select name="items[${idx}][building_id]" class="form-select form-select-sm" ${locked?'disabled':''}><option value="">-</option>${opts(buildings,'id','name',data.building_id)}</select></td><td><select name="items[${idx}][lease_id]" class="form-select form-select-sm" ${locked?'disabled':''}><option value="">-</option>${leases.map(l=>`<option value="${l.id}" ${String(l.id)===String(data.lease_id||'')?'selected':''}>${l.lease_number} - ${l.building_name} ${l.unit_number}</option>`).join('')}</select></td><td class="lineTotal">0.00</td><td>${locked?'': '<button type="button" class="btn btn-sm btn-danger rem">x</button>'}</td>`;document.querySelector('#billLines tbody').appendChild(tr);idx++;calc()}function calc(){document.querySelectorAll('#billLines tbody tr').forEach(tr=>{let q=parseFloat(tr.querySelector('.qty').value)||0,r=parseFloat(tr.querySelector('.rate').value)||0,vt=tr.querySelector('select[name*="vat_treatment"]').value;let s=q*r,v=vt==='standard'?s*.05:0;tr.querySelector('input[name*="vat_rate"]').value=vt==='standard'?5:0;tr.querySelector('.lineTotal').textContent=(s+v).toFixed(2);});}document.getElementById('billLines').addEventListener('input',calc);document.getElementById('billLines').addEventListener('change',calc);document.getElementById('billLines').addEventListener('click',e=>{if(e.target.classList.contains('rem')){e.target.closest('tr').remove();calc();}});document.getElementById('addLine')&&(document.getElementById('addLine').onclick=()=>addLine());if(existing.length){existing.forEach(addLine)}else addLine();</script>
